metrics.workdir_dsl:
workspace "Energy Manager" "C4 model of the home energy management platform" {

    configuration {
        scope "SoftwareSystem"
    }

    model {

        homeowner = person "Homeowner" "Uses the platform to manage the household's energy use and costs."

        energyManager = softwareSystem "Energy Manager" "Home energy management platform owned and operated by our company." {

            dashboard = container "Dashboard Web App" "Web app where homeowners see consumption and costs." "Web Application"

            scheduler = container "Scheduling Service" "Service that plans charging and heating." "Service"

            ratesLibrary = container "Rates Library" "Shared library that computes energy prices from tariff and time of day." "Library"

            database = container "Energy Manager Database" "Database that stores meter readings and schedules. Operated by our company." "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "External smart meter provider that supplies live meter readings. Operated by a different organization."

        homeowner -> dashboard "Manages household energy use and costs" "HTTPS"
        dashboard -> ratesLibrary "Embeds" "In-process"
        scheduler -> ratesLibrary "Embeds" "In-process"
        scheduler -> smartMeterProvider "Fetches live meter readings" "HTTPS"
        scheduler -> database "Stores meter readings and schedules" "SQL"
    }

    views {

        systemContext energyManager "SystemContext" {
            include *
            autoLayout
        }

        container energyManager "Containers" {
            include *
            autoLayout
        }
    }
}
